esqlQuery.esql:
// Alert when a model's request-weighted cache hit rate over the last 6 hours falls below half of
// its own rate over the rest of the rule window (the preceding days).
// Models that do not use prompt caching (baseline below 10%) and quiet models (fewer than 20
// requests in the last 6 hours) are ignored.
// Tuning: 6 hours = recent period, 0.10 = minimum baseline rate, 20 = minimum recent requests,
// 0.5 = fraction of the baseline below which to alert.
FROM metrics-openrouter.performance-*
| WHERE openrouter.performance.cache_hit_rate IS NOT NULL AND openrouter.performance.request_count > 0
| EVAL recent = @timestamp >= NOW() - 6 hours, hits = openrouter.performance.cache_hit_rate * openrouter.performance.request_count
| STATS recent_hits = SUM(hits) WHERE recent, recent_req = SUM(openrouter.performance.request_count) WHERE recent,
        base_hits = SUM(hits) WHERE NOT recent, base_req = SUM(openrouter.performance.request_count) WHERE NOT recent
  BY openrouter.performance.model
| EVAL recent_rate = recent_hits / recent_req, baseline_rate = base_hits / base_req
| WHERE baseline_rate >= 0.10 AND recent_req >= 20 AND recent_rate < baseline_rate * 0.5
| KEEP openrouter.performance.model, recent_rate, baseline_rate, recent_req
